HRESULT __stdcall CBasePin::Connect(IPin* pReceivePin, const AM_MEDIA_TYPE* pmt)
{
    if (pReceivePin == 0) return (HRESULT)0x80004003L;   // CheckPointer(pReceivePin, E_POINTER)
    CAutoLock cObjectLock(m_pLock);
    DisplayPinInfo(pReceivePin);

    /* See if we are already connected */

    if (m_Connected) {
        return (HRESULT)0x80040204L;                      // VFW_E_ALREADY_CONNECTED
    }

    /* See if the filter is active */
    if (!IsStopped() && !m_bCanReconnectWhenActive) {
        return (HRESULT)0x80040224L;                      // VFW_E_NOT_STOPPED
    }

    // Find a mutually agreeable media type -
    // Pass in the template media type. If this is partially specified,
    // each of the enumerated media types will need to be checked against
    // it. If it is non-null and fully specified, we will just try to connect
    // with this.

    const CMediaType* ptype = (CMediaType*)pmt;
    HRESULT hr = AgreeMediaType(pReceivePin, ptype);
    if (hr < 0) {                                          // FAILED(hr)
        // Since the procedure is already returning an error code, there
        // is nothing else this function can do to report the error.
        BreakConnect();                                    // EXECUTE_ASSERT(SUCCEEDED(BreakConnect()))
        return hr;
    }

    return 0;                                              // NOERROR
}

